using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace OpenWeatherMapConsoleTool
{
    class Program
    {
        static async Task Main(string[] args)
        {
            var city = args[0];
            var apiKey = "YOUR_API_KEY";

            try
            {
                var client = new HttpClient { Timeout = TimeSpan.FromSeconds(10) };
                var response = await client.GetAsync($"http://api.openweathermap.org/data/2.5/weather?q={city}&appid={apiKey}");

                response.EnsureSuccessStatusCode();

                var weatherData = JsonConvert.DeserializeObject<WeatherData>(await response.Content.ReadAsStringAsync());
                Console.WriteLine($"Temperature: {weatherData.Main.Temp}°C");
                Console.WriteLine($"Humidity: {weatherData.Main.Humidity}%");
                Console.WriteLine($"Wind Speed: {weatherData.Wind.Speed} m/s");
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Unexpected error: {ex.Message}");
            }
        }
    }

    public class WeatherData
    {
        public Main Main { get; set; }
        public Wind Wind { get; set; }
    }

    public class Main
    {
        public double Temp { get; set; }
        public double Humidity { get; set; }
    }

    public class Wind
    {
        public double Speed { get; set; }
    }
}
