// Beginner notes: Express = simple web server. CORS = allows frontend calls. Try/catch = handles errors gracefully.
import express from 'express';
import cors from 'cors';

const app = express();
const PORT = 3000;

// Middleware: Enables CORS (browser-friendly), parses JSON.
app.use(cors());
app.use(express.json());

// ONE endpoint: /iss → fetches ISS position from public API.
app.get('/iss', async (req, res) => {
  try {
    const apiRes = await fetch('http://api.open-notify.org/iss-now.json');  // HTTP OK here (server-side)
    if (!apiRes.ok) throw new Error('API down');
    const data = await apiRes.json();
    res.json(data);  // Returns { iss_position: { latitude, longitude }, timestamp }
  } catch (error) {
    console.error('Proxy error:', error);  // Logs for debugging
    res.status(500).json({ error: 'Fetch failed—try later!' });  // User-friendly
  }
});

app.listen(PORT, () => {
  console.log(`Proxy running at http://localhost:${PORT}/iss`);
});
```

